// swift-tools-version: 6.0
// Run scripts/build-core.sh first: it builds the Rust core and generates App/Vendor/.
import Foundation
import PackageDescription

let vendor = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Vendor").path

let package = Package(
    name: "Tilde",
    platforms: [.macOS(.v14)],
    dependencies: [
        // Hosts Neovim for EDIT (docs/SPEC.md §6.9).
        .package(url: "https://github.com/migueldeicaza/SwiftTerm", exact: "1.20.0"),
    ],
    targets: [
        // C header and module map generated by UniFFI.
        .systemLibrary(name: "tilde_ffiFFI", path: "Vendor/include"),
        // Generated Swift bindings plus the Rust static library.
        .target(
            name: "TildeFFI",
            dependencies: ["tilde_ffiFFI"],
            path: "Vendor/swift",
            swiftSettings: [.swiftLanguageMode(.v5)],
            linkerSettings: [
                .unsafeFlags(["-L\(vendor)/lib"]),
                .linkedLibrary("tilde_ffi"),
            ]
        ),
        .executableTarget(
            name: "Tilde",
            dependencies: ["TildeFFI", .product(name: "SwiftTerm", package: "SwiftTerm")],
            path: "Sources/Tilde",
            // KaTeX for maths in the Markdown preview.
            resources: [.copy("Resources/katex")]
        ),
        // The app's own logic (keys, jump list, history graph). Run with `swift test`.
        .testTarget(
            name: "TildeTests",
            dependencies: ["Tilde"],
            path: "Tests/TildeTests"
        ),
    ]
)
